	await host.caps.refresh();
	turn.install();
	leader.start();
	tasks.start();
	cost.install();
	ui.mount();
	ui.registerCoreViews({
		inbox,
		journal,
		autonomy,
		cost,
		modules,
		settings,
		caps: host.caps,
		tasks,
		i18n
	});
	const offDataActions = installDataActions(app);
	await modules.startAll(app);
